    pub(crate) async fn snapshot(
        &self,
        request: &super::model::ScopeContextInput,
    ) -> Result<SshForwardSnapshot, SshForwardCommandError> {
        let _command = self.command_gate.lock().await;
        self.checked_scope(
            &request.context,
